{
  "provider": "LM Studio (http://localhost:1234/v1)",
  "source": "from docs: LM Studio OpenAI-compat error envelope",
  "model": "foo",
  "http": {
    "status": 404,
    "contentType": "application/json"
  },
  "expect": {
    "error": {
      "code": "INVALID_REQUEST",
      "status": 404,
      "messageIncludes": "not found"
    }
  },
  "body": "lmstudio-404-model.json"
}

{
  "provider": "vLLM (OpenAI-compatible server)",
  "source": "from docs: vLLM ErrorResponse ({\"object\":\"error\",\"message\",\"type\",\"param\",\"code\": <int>})",
  "model": "Qwen/Qwen3-8B",
  "http": {
    "status": 400,
    "contentType": "application/json"
  },
  "expect": {
    "error": {
      "code": "CONTEXT_WINDOW_EXCEEDED",
      "status": 400
    }
  },
  "body": "vllm-400-context.json"
}

{
  "error": {
    "message": "该模型未开通，请先在百炼控制台开通模型服务",
    "type": "invalid_request_error",
    "param": null,
    "code": "Model.NotActivated"
  }
}

{
  "provider": "vLLM (OpenAI-compatible server)",
  "source": "from docs: vLLM serving_chat streams an in-band `data: {\"error\": …}` frame when generation fails mid-stream",
  "model": "Qwen/Qwen3-8B",
  "http": {
    "status": 200,
    "contentType": "text/event-stream"
  },
  "expect": {
    "error": {
      "code": "SERVER",
      "messageIncludes": "CUDA out of memory"
    }
  },
  "body": "vllm-midstream-error.sse"
}

{
  "provider": "Moonshot Kimi (api.moonshot.cn/v1)",
  "source": "from docs: platform.moonshot.cn/docs/api/errors",
  "model": "kimi-nope",
  "http": {
    "status": 404,
    "contentType": "application/json"
  },
  "expect": {
    "error": {
      "code": "INVALID_REQUEST",
      "status": 404,
      "messageIncludes": "Not found the model"
    }
  },
  "body": "kimi-400-model.json"
}

{
  "provider": "OpenAI (api.openai.com/v1)",
  "source": "from docs: platform.openai.com/docs/guides/error-codes",
  "model": "gpt-9",
  "http": {
    "status": 404,
    "contentType": "application/json"
  },
  "expect": {
    "error": {
      "code": "INVALID_REQUEST",
      "status": 404,
      "messageIncludes": "does not exist or you do not have access"
    }
  },
  "body": "openai-404-model.json"
}
